window.SAQ_PAPER_QUESTIONS["2024-2-liverpool"]=[{"number":1,"title":"","stemText":"A 27 year old man presents following an assault. He had a GCS of 5 at the scene and has been intubated prior to hospital arrival.\nHis vital signs in ED are:\n\nHR\n\nBP\n120/70\n\nSats\n99% A CT scan has been performed.","parts":[{"id":"a","label":"Part A","prompt":"Describe three (3) abnormalities on the CT scan. (3 marks) 1.________________________________________________________________________________ 2.________________________________________________________________________________ 3.________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"He is going to the operating theatre in 60 minutes. Describe six (6) neuroprotective interventions you will perform in the ED prior to theatre. Give specific doses and endpoints where relevant. (6 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ 6. ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"While awaiting theatre, he develops a unilateral dilated pupil. List three (3) immediate actions you would take. (3 marks) 1.________________________________________________________________________________ 2.________________________________________________________________________________ 3.________________________________________________________________________________"}],"propPages":["asset:imgf589b47f9c9ac8fb30"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">3rd ventricle</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div><div class=\"answer-line\">1. <strong>Extradural  haematoma adjacent to the right frontal lobe </strong>(just anterior to Sylvian</div><div class=\"answer-line\">fissure )</div><div class=\"answer-line\">2. Midline shift few mm (subfalcine herniation- see diagram below)</div><div class=\"answer-line\">3. Surrounding vasogenic oedema with mass effect and effacement of surrounding sulci</div><div class=\"answer-line\">4. Displaced skull # parietal bone /frontal bone (near coronal suture)</div><div class=\"answer-line\">5. Scalp haematoma right frontal region</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Maintain low normal pCO2 35 mmHg</div><div class=\"answer-line\">2. Maintain BP – SBP &gt;90</div><div class=\"answer-line\">3. Avoid any hypoxia and hyperoxia - minimum FiO2 to maintain sats &gt;95%</div><div class=\"answer-line\">4. Head up 30 degrees</div><div class=\"answer-line\">5. Avoid neck compression with ETT ties or collar</div><div class=\"answer-line\">6. Maintain normoglycaemia</div><div class=\"answer-line\">7. Avoid hypo and hyperthermia (target 35-37 degrees)</div><div class=\"answer-line\">8. Sedation/paralyse to allow appropriate ventilation and avoid hypertension</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Hyperosmolar therapy – either mannitol 20% 0.5-1g/kg or 3% saline 3ml/kg IV</div><div class=\"answer-line\">2. Hyperventilate to PCO2 ~30mmHg</div><div class=\"answer-line\">3. Call NeuroSx to expedite OT</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 35 year old man presents following an industrial injury. His vital signs are currently stable.","parts":[{"id":"a","label":"Part A","prompt":"List the five (5) most important injuries that may be associated with this wound. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"If this patient progressed to cardiac arrest in the Emergency Department, what would be four (4) specific goals of an ED thoracotomy. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":["asset:imgef4138a0d8ca03db8d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">4. Massive haemothorax</div><div class=\"answer-line\">5. Bronchial injury</div><div class=\"answer-line\">6. Lung contusion/haemorrhage</div><div class=\"answer-line\"><strong>SAQ 2 (b) </strong></div><div class=\"answer-line\"><strong>1. Finger thoracostomy at start to relieve tension pneumothorax  </strong></div><div class=\"answer-line\"><strong>2. Release cardiac tamponade (pericardiotomy) </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 53 year old man presents with light headedness for 2 hours. He has a history of ischaemic heart disease with previous stents. On examination he is alert with a BP 70/45 following a 500ml bolus of normal saline. This is his ECG.","parts":[{"id":"a","label":"Part A","prompt":"Describe three (3) key findings on the ECG. (3 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark) 1. ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"You decide to perform electrical cardioversion. Outline six (6) key steps in performing cardioversion in this patient. Give doses and drug names where relevant. (6 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ 6. ________________________________________________________________________________"}],"propPages":["asset:img430659cbd65d1940c2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Tachycardia ~200/min</div><div class=\"answer-line\">2. Regular</div><div class=\"answer-line\">3. Wide QRS ~0.14msec   (4. Second last complex in V1,2,3 is a fusion beat)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1.  Conscious Unstable Ventricular tachycardia</div><div class=\"answer-line\">c)  Outline 6 steps in his immediate treatment. Give doses and drug names where relevant.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Prepare for electrical cardioversion(Synchronized) – resus bed, P/BP/sats</div><div class=\"answer-line\">monitoring, at least 3 staff (1 Dr, 2RN or Dr)</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 35 year old woman walks into the ED from a nearby radiology practice. She had a head CT\nperformed following a 2-week history of headaches.\nCT Image attached.","parts":[{"id":"a","label":"Part A","prompt":"Describe three (3) key findings on the CT scan image. (3 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List the two (2) most likely diagnostic categories which may cause these findings and give a specific example for each category. (4 marks) Diagnostic category Example She has a self-limiting 2-minute grand mal seizure shortly after arriving in the ED and is now post-ictal. She is maintaining her own airway and is afebrile and haemodynamically stable with an improving level of consciousness."},{"id":"c","label":"Part C","prompt":"List two (2) specific treatments you would administer including route and dosage. (4 marks) Specific treatment Medication including dosage and route"}],"propPages":["asset:img0fb2054a68ee5b03fe"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div><div class=\"answer-line\">Axial slice CT brain + IV contrast</div><div class=\"answer-line\"><strong>1. Large single ring enhancing lesion right occipital lobe </strong></div><div class=\"answer-line\">2. Possible acute haemorrhage into lesion v calcification posteriorly</div><div class=\"answer-line\">3. Surrounding vasogenic oedema</div><div class=\"answer-line\">4. Mass effect with mild effacement occipital horn right lateral ventricle</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>1. Infective-  eg. Pyogenic Cerebral abscess, tuberculoma, CNS toxoplasmosis, fungal</td><td>infection, cryptococcoma</td></tr><tr><td>2. Malignancy- Primary brain tumour-meningioma, astrocytoma, glioblastoma, CNS</td><td>lymphoma, secondary-breast, lung, melanoma,</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">1. Anticonvulsant – Phenytoin 20mg/kg over 30 minutes or Levetiracetam 60mg/kg</div><div class=\"answer-line\">up 4500mg or Valproate 40mg/kg up to 3000mg (doses for adults )</div><div class=\"answer-line\">2. Steroid to reduce mass effect – dexamethasone 8mg IV</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 5 year old girl presents with a painful elbow following a fall in the playground at school. She is distressed with pain. This is her X-ray.","parts":[{"id":"a","label":"Part A","prompt":"Describe three (3) key findings on the x-ray. (3 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Outline the four (4) key findings you will assess on clinical examination. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Describe two (2) interventions you would initiate in the first 30 minutes to provide analgesia for this girl. (2 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________"}],"propPages":["asset:imgbf2f75be20c9f2e2d2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Supracondylar humeral fracture  </strong></td></tr><tr><td>-</td><td><strong>Fracture off-ended with distal fragment sitting posteriorly (Gartland 3) </strong>(complete</td></tr><tr><td colspan=\"2\">disruption of anterior humeral line)</td></tr><tr><td>-</td><td>No subcutaneous emphysema to suggest open fracture</td></tr><tr><td>-</td><td>Relative preservation of the radiocapitellar line</td></tr><tr><td>-</td><td>Soft tissue swelling</td></tr><tr><td colspan=\"2\">Clinical Practice Guidelines : Supracondylar fracture of the humerus - Emergency Department</td></tr><tr><td colspan=\"2\">(rch.org.au)</td></tr><tr><td colspan=\"2\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Neurovascular status (PASS/FAIL): </strong></td></tr><tr><td>-</td><td><strong>Peripheral pulses (potential brachial artery injury) </strong></td></tr><tr><td>-</td><td><strong>Peripheral nerve assessment (radial, ulna, median nerves) </strong></td></tr><tr><td>-</td><td>Distal radioulnar joint</td></tr><tr><td>-</td><td>Evidence of other injuries from fall</td></tr><tr><td>-</td><td>Evidence of open fracture</td></tr><tr><td>-</td><td>Skin tenting or evidence of pressure necrosis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Immobilisation with Above Elbow back slab / elevation<strong> </strong></div><div class=\"answer-line\">-</div><div class=\"answer-line\">Analgesia- <strong> Fentanyl, Intranasal, 1.5mcg/kg </strong>or intravenous, 0.5-1.0mcg/kg or other</div><div class=\"answer-line\">opioid<strong> </strong></div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 17 year old girl is brought to ED with acute confusion after ingesting a large number of unknown tablets following an argument with her boyfriend.\nHer vital signs are:\n\nHR\n120/min\n\nRR\n40/min\n\nBP\n130/80\n\nGCS\nHer ABG on room air and biochemistry results attached.\n\npH\n7.30\n\npO2\n\npCO2 18\n\nHCO3 10\n\nBE\n-18\n\nNa\n143 (135-145)\n\nK\n3.0 (3.2-4.5)\n\nCl\n103 (99-110) Ur 5.0 (3.0-8.0)\n\nCr\n152 (60-120)\n\nGlucose\n5.4 (3.0-6.0)","parts":[{"id":"a","label":"Part A","prompt":"Describe five (5) important abnormalities in these blood tests. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List and justify five (5) further investigations that you would perform in the ED. (5 marks)"},{"id":"c","label":"Part C","prompt":"Describe four (4) interventions you would perform in the ED for the toxin most likely to have caused these findings. Include details of doses and endpoints where relevant. (8 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Severe Metabolic acidosis (low pH, low HCO3, negative BE(-18)</div><div class=\"answer-line\">2. Respiratory alkalosis (pCO2 lower than expected for HCO3 and pH higher than</div><div class=\"answer-line\">expected)</div><div class=\"answer-line\">3. High anion gap (143-10-103=30)</div><div class=\"answer-line\">4. Moderate hypokalaemia</div><div class=\"answer-line\">5. Mild Renal impairment</div><div class=\"answer-line\">6. Significantly raised A-a gradient [expected pO2 = 150-18/0.8 =~120)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>1.Salicylate level</td><td>Findings most likely secondary to salicylate toxicity</td></tr><tr><td>2.CXR</td><td>Raised A-a gradient ?aspiration or ?pulm oedema from salicylate</td></tr><tr><td>3.CT brain</td><td>Low GCS unexplained by salicylates ? trauma</td></tr><tr><td>4 Paracetamol level</td><td>Assess for serious/treatable co ingestants</td></tr><tr><td>5.ECG</td><td>Assess rhythm in view of tachycardia and look for signs of</td></tr><tr><td colspan=\"2\">co ingestants eg TCA</td></tr><tr><td colspan=\"2\">c) Describe Four (4) interventions you would perform in the ED for the toxin most likely to</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Intravenous saline to maintain urine output 2ml/kg/hour – start with 1000ml bolus</div><div class=\"answer-line\">2. Alkalinisation with boluses of 100ml 8.4% HCO3 (1-2mmol/kg) and then infusion to</div><div class=\"answer-line\">achieve urinary pH &gt;7.5</div><div class=\"answer-line\">3. Replace K+ 10-20mmol/hour aim for K&gt;4</div><div class=\"answer-line\">4. Intubation and ventilation (Ketamine 1mg/kg and Roc 1.5mg/kg or other safe choice),</div><div class=\"answer-line\">maintain high RR to avoid secondary Resp acidosis</div><div class=\"answer-line\">5. Charcoal 50g once airway secured and bowel sounds present</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 27 year old woman presents to the ED in precipitous labour. A term infant has been delivered and is in the capable care of the paediatric team. The mother now has ongoing heavy PV bleeding.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) potential causes for bleeding in this patient. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Assuming the placenta has been delivered intact, outline in six (6) sequential steps how you would take to control this woman’s bleeding. (6 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ 6. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Tone (70%) – atonic uterus</div><div class=\"answer-line\">2. Trauma (20%) – Laceration of cervix, vagina or perineum, uterine rupture/inversion</div><div class=\"answer-line\">3. Tissue (10%) – Retained Products, placenta, membranes or clots, abnormal placenta</div><div class=\"answer-line\">4. Thrombin (&lt;1%) – coagulation abnormalities</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1.  Ensure placenta is complete and commence Uterine massage ( +/- bimanual uterine</div><div class=\"answer-line\">compression)</div><div class=\"answer-line\">2. Resuscitation with IVF +/- activate MTP if Severe + Tranexamic acid 1gm IV</div><div class=\"answer-line\">3.  Oxytocin 5-10 units slow IV push (or 10U IM)  +/- infusion 20-40mg in 1L 0.9% NS</div><div class=\"answer-line\">4 . Seek and treat local trauma to the Birth Canal and ensure bladder empty</div><div class=\"answer-line\">5. Ensure obstetrics have been called and are coming as patient may need to go to</div><div class=\"answer-line\">theatre</div><div class=\"answer-line\">6. Ergometrine 0.25-5mg slow IV or IM</div><div class=\"answer-line\"><strong>Other acceptable additions would include seek and treat coagulopathy. </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 23 year old male is brought in by ambulance after his parents found him to be confused and disoriented early this morning. He had been partying at a nightclub with friends the night before.\nHis vital signs are:\n\nTemp 39.4 degrees\n\nHR\n126/min\n\nBP\n110/50 mmhg\n\nGCS\n13/15","parts":[{"id":"a","label":"Part A","prompt":"List five (5) potential causes for his presentation. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List five (5) indications for CT imaging prior to performing a lumbar puncture. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ A lumbar puncture is performed following a normal CT scan CSF results attached.\n\nCSF results\nNormal ranges\n\nGlucose\n< 0.3 mmol/L Protein 5.78 g/L (0.15 - 0.40 g/L) Polymorphs 8000 x106 /L Lymphocytes 102 x106 /L RBCs 975 Gram stain: Gram negative diplococci"},{"id":"c","label":"Part C","prompt":"List four (4) important CSF findings. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Intracerebral infection / Meningoencephalitis  </strong></td></tr><tr><td>-</td><td>Heat illness / Heat stroke</td></tr><tr><td>-</td><td>Toxicological<em>: </em></td></tr><tr><td colspan=\"2\">- Sympathomimetic toxidrome</td></tr><tr><td colspan=\"2\">- Serotonin syndrome</td></tr><tr><td colspan=\"2\">- Neuroleptic malignant syndrome</td></tr><tr><td colspan=\"2\">- Anticholinergic toxidrome</td></tr><tr><td>-</td><td>Seizure (postictal phase)</td></tr><tr><td>-</td><td>Hypoglycaemia</td></tr><tr><td>-</td><td>Thyroid storm</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Altered mental status or deteriorating level of consciousness</td></tr><tr><td>-</td><td>Focal neurological deficit</td></tr><tr><td>-</td><td>New Seizure</td></tr><tr><td>-</td><td>Papilledema</td></tr><tr><td>-</td><td>Immunocompromised state</td></tr><tr><td>-</td><td>History of focal CNS disease (stroke, abscess, tumour)</td></tr><tr><td>-</td><td>Concern for CNS mass lesion/suspected metastatic cancer</td></tr><tr><td colspan=\"2\">A lumbar puncture is performed following a normal CT scan</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Gram negative diplococci = most likely Neisseria meningitis</td></tr><tr><td>•</td><td>Markedly elevated polymorph cell count</td></tr><tr><td>•</td><td>Very low (or undetectable) CSF glucose</td></tr><tr><td>•</td><td>Very high CSF protein</td></tr><tr><td>•</td><td>Findings consistent with bacterial meningitis</td></tr><tr><td colspan=\"2\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 36 year old female is brought into the Emergency Department after being found unconscious in her car. She was parked in her home garage with the engine still running.\nHer vital signs are:\n\nTemp 37.2 degrees\n\nHR\n114/min regular\n\nBP\n125/70mmhg\n\nGCS\n10/15\n\nSats\n95% room air","parts":[{"id":"a","label":"Part A","prompt":"List four (4) key investigations and their rationale (4 marks) Investigation Rationale"},{"id":"b","label":"Part B","prompt":"State your most likely diagnosis (1 mark)"},{"id":"c","label":"Part C","prompt":"Describe four (4) clinical or biochemical findings in the ED which would support this diagnosis. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List four (4) indications for hyperbaric therapy in carbon monoxide poisoning. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">RATIONALE</td></tr><tr><td colspan=\"2\">Blood glucose level Hypoglycaemia as cause for altered consciousness, or ingestion</td></tr><tr><td colspan=\"2\">Tachycardic patient. Non-invasive, readily available. May reveal</td></tr><tr><td>12-lead ECG</td><td>underlying coingestant (e.g. TCA) ?Ischaemic change (COHb</td></tr><tr><td colspan=\"2\">toxicity)</td></tr><tr><td>COHb</td><td>Likely CO poisoning</td></tr><tr><td>β-HCG</td><td>Pregnancy has implications for potential HBO therapy.</td></tr><tr><td>Blood gas</td><td>?acidosis ?lactate level</td></tr><tr><td>Paracetamol or</td><td>Possible coingestion</td></tr><tr><td colspan=\"2\">other drug level</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Carbon monoxide poisoning</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em><strong>Any reasonable four from below, but must have COHb to pass. </strong></em></td></tr><tr><td colspan=\"2\"><strong>BIOCHEMICAL. </strong></td></tr><tr><td>-</td><td><strong>Elevated COHb level </strong> (expect level &gt;30-40% given symptoms, but low levels do not</td></tr><tr><td colspan=\"2\">rule out exposure)</td></tr><tr><td>-</td><td>Metabolic (lactic) acidosis</td></tr><tr><td colspan=\"2\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr><tr><td colspan=\"2\"><strong>CLINICAL</strong></td></tr><tr><td><strong>BODY SYSTEM</strong></td><td><strong>SYMPTOM(S)</strong></td></tr><tr><td colspan=\"2\">• Headache, nausea, dizziness.</td></tr><tr><td colspan=\"2\">• Confusion, poor concentration, MMSE errors.</td></tr><tr><td colspan=\"2\">Central nervous</td></tr><tr><td colspan=\"2\">system</td></tr><tr><td colspan=\"2\">• Incoordination, ataxia</td></tr><tr><td colspan=\"2\">• Seizures, coma.</td></tr><tr><td colspan=\"2\">• Tachycardia &amp; HTN</td></tr><tr><td>Cardiovascular</td><td>• Ischaemic ECG changes or AMI.</td></tr><tr><td colspan=\"2\">• Hypotension or dysrhythmias.</td></tr><tr><td>Respiratory</td><td>• Non-cardiogenic pulmonary oedema</td></tr><tr><td colspan=\"2\">• Lactic acidosis</td></tr><tr><td>Metabolic</td><td>• Rhabdomyolysis</td></tr><tr><td colspan=\"2\">• Hyperglycaemia</td></tr><tr><td>Haematologic</td><td>• DIC</td></tr><tr><td>Other</td><td>• Cherry red skin appearance</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Loss of consciousness or coma </strong></td></tr><tr><td>-</td><td><strong>Abnormal neurological exam:  </strong></td></tr><tr><td>-</td><td>Persistent neurological dysfunction (eg. Confusion)</td></tr><tr><td>-</td><td>Abnormal cerebellar examination</td></tr><tr><td>-</td><td>Abnormal MMSE</td></tr><tr><td>-</td><td>Metabolic acidosis</td></tr><tr><td>-</td><td>Myocardial ischaemia/cardiovascular instability</td></tr><tr><td>-</td><td>Pregnancy</td></tr><tr><td colspan=\"2\">Ref : Murray Tox book</td></tr><tr><td colspan=\"2\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 3 month old child has been brought in by their mother after rolling off the change table. You find that they have a spiral fracture of their right femur. You suspect non-accidental injury.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) fracture patterns in children concerning for a non-accidental cause. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List five (5) features of history and five (5) examination findings that would raise the possibility of non-accidental injury in children. (10 marks) History 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ Examination 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Metaphyseal fractures of long bones  ( path gnomonic of NAI)</div><div class=\"answer-line\">2. Epiphyseal injuries ( Salter harris I or II due to jerking or wretching)</div><div class=\"answer-line\">3.Spiral Fracture of Long Bones  ( especially common with age &lt; 2years : femur,</div><div class=\"answer-line\">tibia,radius)</div><div class=\"answer-line\">4. Scapular, spinus process, sterna and rib fractures</div><div class=\"answer-line\">5. Skull fracture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Inconsistent or changing  history of event</div><div class=\"answer-line\">2. Delay in seeking treatment</div><div class=\"answer-line\">3. Onset of injury does not fit the developmental age of the child</div><div class=\"answer-line\">4. Different care giver presenting with child as to whom witnessed injury</div><div class=\"answer-line\">5. Unwitnessed injury</div><div class=\"answer-line\">Would also accept: history of recurrent fractures, unexplained soft tissue markings,</div><div class=\"answer-line\">unexplained tension/anxiety, regression in developmental milestones</div><div class=\"answer-line\"><strong>Examination</strong></div><div class=\"answer-line\">1. General observations – detached, depressed, hostile or defensive child who may</div><div class=\"answer-line\">make poor eye contact</div><div class=\"answer-line\">2.  Bruising  of varying ages and  sites particularly on soft tissue areas</div><div class=\"answer-line\">3. Burns, scalds or branding  -  to feet and buttocks ( dunking  pattern) or immersion</div><div class=\"answer-line\">without splash marks, or  classically cigarette burn to palms/soles)</div><div class=\"answer-line\">4. Lacerations or abrasions</div><div class=\"answer-line\">5. General signs of neglect  - poor hygiene, severe nappy rash, impaired growth</div><div class=\"answer-line\">centiles</div><div class=\"answer-line\">Would also accept – eye injuries – subconjunctival haemorrhages or retinal haemorrhages</div><div class=\"answer-line\">(although difficult to ascertain in ED), Ear Injuries – drum rupture, pinna damage, severe</div><div class=\"answer-line\">abdominal pain with bruising, Significant head injury</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 42 year old male with known alcoholic liver disease is brought in by relatives with a 3-day history of worsening confusion. On examination, he is confused with marked abdominal distension and generalised tenderness.\nHis vital signs are as follows:\n\nTemp 35oC\n\nHR\n70/min\n\nBP\n90mmhg\n\nSats\n98% on 6L oxygen via Hudson mask","parts":[{"id":"a","label":"Part A","prompt":"Outline six (6) potential causes of confusion in this man with the relevant investigation for each listed cause. (6 marks) CAUSE OF CONFUSION INVESTIGATION During your assessment he passes a large melaena. His vital signs remain unchanged."},{"id":"b","label":"Part B","prompt":"Outline five (5) specific interventions to manage this clinical condition. (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cause Confusion</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">BSL</div><div class=\"answer-line\">SDH/ICH related to trauma, decreased Plt count CT brain, coags, FBC</div><div class=\"answer-line\">*Alcohol intoxication</div><div class=\"answer-line\">ETOH level</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 34 year old female with presents with sudden onset right flank pain.\nLimited slices of her CT KUB are shown below.","parts":[{"id":"a","label":"Part A","prompt":"Outline three (3) important findings on her CT KUB. (3 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List six (6) indications for hospital admission in patients with renal colic. (6 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ 6. ________________________________________________________________________________ While in the ED she develops a fever to 39 degrees and becomes hypotensive and tachycardia."},{"id":"c","label":"Part C","prompt":"List three (3) key treatments she now requires with details of the specific therapies. (3 marks) Treatment with details of the specific therapies"}],"propPages":["asset:imgdfb9c261da6eb7162c","asset:imge7b5de70876231edda"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Severe right-sided hydronephrosis and hydroureter</div><div class=\"answer-line\">2. Distal right ureteric calculus-VUJ</div><div class=\"answer-line\">3. Right perinephric stranding</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Urological admission</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">•urinary infection</div><div class=\"answer-line\">•high degree of obstruction</div><div class=\"answer-line\">•large (&gt; 6mm) proximal stone</div><div class=\"answer-line\">•bilateral ureteric stones</div><div class=\"answer-line\">•significant renal impairment and associated urinary obstruction</div><div class=\"answer-line\">•persistent or multiple repetitive episodes of pain requiring parenteral analgesia</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 27 year old male is brought in to Emergency after falling from his Motorcross bike at high speed.He has been intubated pre-hospital and is being ventilated on an Oxylog ventilator.\nHis vital signs are as follows:\n\nHR\n140\n\nBP\n\nSats\n85% FAST demonstrates peritoneal free fluid without pericardial effusion. He clinically has a right femur fracture.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) findings on his CXR (5 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Outline four (4) interventions you would use to optimise his oxygen saturations. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":["asset:img8703ceec329c2cbfe4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Large right flail segment with multiple depressed rib fractures.</div><div class=\"answer-line\">2. Bilateral intercostal catheters</div><div class=\"answer-line\">3. Intubated. Good position above carina.</div><div class=\"answer-line\">4. Bilateral opacifications. Likely bilateral contusions</div><div class=\"answer-line\">5. Right haem/pneumothorax</div><div class=\"answer-line\">6. Bilateral subcutaneous emphysema</div><div class=\"answer-line\">7. No nasogastric tube</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1.</div><div class=\"answer-line\">Ventilate with 100% O2</div><div class=\"answer-line\">2. Add PEEP if BP tolerates-concurrent fluid resuscitation/splint femoral # (must clarify</div><div class=\"answer-line\">addressing BP 1st)</div><div class=\"answer-line\">3. Adequate sedation and paralysis</div><div class=\"answer-line\">4. Positioning-Sit up</div><div class=\"answer-line\">5. NG to decompress stomach</div><div class=\"answer-line\">6. Additional right sided ICD</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A young woman with an estimated weight of 50kg has just been intubated for severe asthma and is currently being ventilated on 100% oxygen. Her arterial blood gas is attached. Arterial Blood Gas\n\npH 6.94\n\npO2 459\n\npCO2 134\n\nHCO3 27\n\nBE -7\n\nLactate 8.94","parts":[{"id":"a","label":"Part A","prompt":"Describe four (4) abnormalities on the blood gas. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Fill in the table below demonstrating your initial choice of ventilator settings, including a brief rationale. (10 marks)"},{"id":"c","label":"Part C","prompt":"Following intubation, the patient becomes bradycardic and hypotensive. Outline, IN SEQUENCE, your initial 6 steps in response to this scenario (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">pH 6.94</div><div class=\"answer-line\">pO2 459</div><div class=\"answer-line\">pCO2 134</div><div class=\"answer-line\">HCO3 27</div><div class=\"answer-line\">BE -7</div><div class=\"answer-line\">Lactate 8.94</div><div class=\"answer-line\">1. <strong>Life-threatening acidosis (predominantly respiratory acidosis</strong> but metabolic</div><div class=\"answer-line\">component as well).</div><div class=\"answer-line\"><strong>2. Severe hypercarbia </strong></div><div class=\"answer-line\">3. Mild metabolic acidosis</div><div class=\"answer-line\">4. Severe elevation of lactate</div><div class=\"answer-line\">5. Other options could include:</div><div class=\"answer-line\">Marked hyperoxia, consider decreasing inspired oxygen to titrate to PaO2</div><div class=\"answer-line\">between 200-300mmHg</div><div class=\"answer-line\"><strong>***Mandatory in BOLD </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Tidal volume</div><div class=\"answer-line\">300-400mL (6-8mL/Kg)</div><div class=\"answer-line\">Aiming to avoid excessive intrinsic</div><div class=\"answer-line\">PEEP, breath-stacking, barotrauma</div><div class=\"answer-line\">Respiratory rate</div><div class=\"answer-line\">Low rates 4-8/min</div><div class=\"answer-line\">Avoid PEEP, breath-stacking, allow</div><div class=\"answer-line\">adequate exhalation time</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. <strong>DISCONNECT FROM VENTILATOR</strong>. BVM patient at low rate connected to high flow</div><div class=\"answer-line\">oxygen.</div><div class=\"answer-line\"><strong>2. SEEK AND TREAT CAUSE : </strong></div><div class=\"answer-line\">a. ETT tube obstruction ➔ sputum plug, kink. Suction tube or replace ETT.</div><div class=\"answer-line\">b. Right main-stem endobronchial intubation. Withdraw tube and reassess.</div><div class=\"answer-line\"><strong>c. Breath stacking </strong>➔<strong> external chest compression </strong></div><div class=\"answer-line\">d. Hypovolaemia (rare) but IV fluid bolus reasonable.</div><div class=\"answer-line\">e. <strong>Consider anaphylactic reaction</strong> to intubation induction agents. Treat along</div><div class=\"answer-line\">standard lines.</div><div class=\"answer-line\">f. <strong>Tension pneumothorax</strong>. Can be diagnosed on ultrasound. If any significant</div><div class=\"answer-line\">delay to diagnose and no response to above measures ➔ empirical bilateral</div><div class=\"answer-line\">finger thoracostomies</div><div class=\"answer-line\"><strong>***Mandatory in BOLD. </strong>In general, if a structured approach to the deteriorating intubated</div><div class=\"answer-line\">asthmatic patient, then reasonable options considered. Other options would be deepening</div><div class=\"answer-line\">sedation, neuromuscular paralysis, but BOLD OPTIONS need to be included to pass.<strong> </strong></div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 21 year old woman presents after collapse following a three day history of vomiting.\nHer ECG and arterial blood gas are attached.","parts":[{"id":"a","label":"Part A","prompt":"List the major abnormality on this ECG. (1 mark)"},{"id":"b","label":"Part B","prompt":"List three (3) possible causes of this abnormality. (3 marks) 1.________________________________________________________________________________ 2.________________________________________________________________________________ 3.________________________________________________________________________________ Arterial Blood Gas\n\npH 7.65\n\nPCO2 55\n\nPO2 80\n\nHCO3 60\n\nBE >+30\n\nK 2.3\n\nCl 69"},{"id":"c","label":"Part C","prompt":"List four (4) major abnormalities on the blood gas. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List four (4) potential causes for these blood gas findings. (4 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________"}],"propPages":["asset:imgcff129bdb568972445"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>1. Profound metabolic alkalosis on basis of elevated pH, BE and bicarbonate. </strong></div><div class=\"answer-line\"><strong>Alkalosis is poorly tolerated compared with acidosis. </strong></div><div class=\"answer-line\">2. Moderate hypercarbia. At maximal compensation [ (0.7 x HCO3) +20 ➔ 62</div><div class=\"answer-line\">calculated]</div><div class=\"answer-line\">3. <strong>Moderately severe hypokalaemia</strong>. Likely cause of pseudo-prolonged QT due to T-</div><div class=\"answer-line\">U fusion complex. Concern for arrhythmia as cause of collapse.</div><div class=\"answer-line\">4. Moderately severe hypochloraemia</div><div class=\"answer-line\"><strong>***Mandatory in BOLD </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">A sensible list of differentials is reasonable. If vomiting is mentioned as a cause, then a</div><div class=\"answer-line\">discussion of potential causes of vomiting (infectious, toxic/metabolic, obstructive) should be</div><div class=\"answer-line\">included. Given age, added weight should be given to both eating disorders as well as</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">C = Contraction</td></tr><tr><td>•</td><td>L = Loop diuretics, licorice</td></tr><tr><td>•</td><td>E = Endocrine (hyperaldosteronism, Bartter’s Conn’s, Cushings)</td></tr><tr><td>•</td><td>V = Vomiting (including NG suction)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">R = Renal bicarbonate retention</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 45 year old male with a history of Marfan’s syndrome presents with abrupt onset severe\nanterior chest pain with nausea and vomiting. His observations are as follows:\n\nHR\n120\n\nBP\n185/60\n\nRR\n\nSats\n99% His ECG demonstrates no acute changes, his CXR shows a widened mediastinum. You suspect acute aortic dissection.","parts":[{"id":"a","label":"Part A","prompt":"List two (2) imaging modalities for this condition with three (3) pros and three (3) cons for each modality. (6 marks) Modality Pros Cons"},{"id":"d","label":"Part D","prompt":"An image of the patient’s CT aortogram is attached i) Which type of aortic dissection is seen on this CT image. (1 mark) ii) What is the definitive treatment for this Type of aortic dissection? (1 mark)"},{"id":"c","label":"Part C","prompt":"Outline three (3) pharmacologic treatments for this patient in next 30mins including specific agents, doses, targets and end points in order of priority. (3 marks) 1.________________________________________________________________________________ 2.________________________________________________________________________________ 3.________________________________________________________________________________"}],"propPages":["asset:img623656439f8dacb5f6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>MODALITY</td><td>PROS CONS</td></tr><tr><td>Transthoracic</td><td>Portable, bedside study (thus can Poor sensitivity due to lack</td></tr><tr><td>echocardiogram</td><td>be used in unstable patients) of visualisation of thoracic</td></tr><tr><td>Gives alternative diagnoses</td><td>aorta (65%)</td></tr><tr><td>Picks up complications, most</td><td>Requires skilled operator to</td></tr><tr><td>notably aortic regurgitation and</td><td>perform and interpret</td></tr><tr><td>tamponade.</td><td></td></tr><tr><td>No radiation or contrast load</td><td></td></tr><tr><td>Transoesophaeal</td><td>Bedside, can be done in unstable Requires skilled operator</td></tr><tr><td>echocardiogram</td><td>patients to perform and interpret</td></tr><tr><td>Very sensitive and specific</td><td>Requires sedation (both</td></tr><tr><td>(&gt;98% for both)</td><td>departmental consideration</td></tr><tr><td>Can pick up complications</td><td>and unstable patient</td></tr><tr><td>No radiation or contrast load</td><td>requiring sedative drugs)</td></tr><tr><td><strong>CT angiogram </strong></td><td>Rapid, readily available. Requires transfer of</td></tr><tr><td>Diagnostic mode of choice in</td><td>unstable patient to CT</td></tr><tr><td>most locations</td><td>scanner</td></tr><tr><td>100% sensitivity, 98% specificity</td><td>Contrast load</td></tr><tr><td>Provides alternative diagnosis</td><td>Radiation load</td></tr><tr><td>Information about complication</td><td></td></tr><tr><td>(haemothorax, extension of</td><td></td></tr><tr><td>dissection to</td><td></td></tr><tr><td>carotids/lumbar/mesenteric</td><td></td></tr><tr><td>vessel/renal arteries/iliac vessels</td><td></td></tr><tr><td>MR angiogram</td><td>Sensitivity and specificity Poor availability</td></tr><tr><td>excellent (98% for both)</td><td>Prolonged time to</td></tr><tr><td>Can pick up low-grade</td><td>complete, thus taking away</td></tr><tr><td>dissections in stable patients</td><td>from OT or resus</td></tr><tr><td>No contrast, non-invasive</td><td>environment</td></tr><tr><td>CXR</td><td>Quick. Can be done at the Findings are non-specific.</td></tr><tr><td>bedside. Abnormal in 80-90%</td><td>Can be normal in up to</td></tr><tr><td>including  mediastinal widening,</td><td>12%. Mediastinal widening</td></tr><tr><td>double density suggesting true</td><td>can be difficult to</td></tr><tr><td>and false lumen, obliteration of</td><td>differentiate from aortic</td></tr><tr><td>aortic arch and deviation of</td><td>tortuosity.</td></tr><tr><td>trachea to right.</td><td></td></tr><tr><td>FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td><td></td></tr><tr><td><strong>***CT ANGIOGRAM IS MANDATORY FOR CANDIDATE TO PASS </strong></td><td></td></tr><tr><td>REASONABLE DISCUSSION OF PROS AND CONS OF EACH OF THE MODALITIES</td><td></td></tr><tr><td>LISTED ABOVE. If basic imaging, such as CXR is listed, then this needs to clarified as a far</td><td></td></tr><tr><td>from ideal imaging choice that neither rules or rules out dissection.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Definitive management is cardiothoracic surgery. No other option is</div><div class=\"answer-line\">considered acceptable.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>- Initially control HR with titrated doses of beta-blockers</strong>. Can use any agent, so long as</div><div class=\"answer-line\">rationale/dose are safe. E.G. esmolol infusion with bolus(500 mcg/kg IV loading dose, then</div><div class=\"answer-line\">infuse at 25 to 50 mcg/kg per minute) vs recurrent doses of 1mg IV metoprolol.</div><div class=\"answer-line\">End points would be HR ~60. Higher end candidates may recognise problems with</div><div class=\"answer-line\">extravasation of esmolol</div><div class=\"answer-line\">- Administration of vasodilator. Again, any option is reasonable</div><div class=\"answer-line\">SNP infusion sodium nitroprusside 0.3 micrograms/kg/minute by intravenous infusion, increasing</div><div class=\"answer-line\">by 0.5 micrograms/kg/minute every 5 minutes, up to 10 micrograms/kg/minute OR</div><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 37-year-old woman presents following a high speed motor vehicle accident.\nShe is alert and oriented.HR 100/min BP 100/60 mmhg Her pelvic x-ray attached.","parts":[{"id":"a","label":"Part A","prompt":"Describe six (6) findings on the x-ray. (6 marks) 1. ________________________________________________________________________________ 2. ________________________________________________________________________________ 3. ________________________________________________________________________________ 4. ________________________________________________________________________________ 5. ________________________________________________________________________________ 6. ________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What specific neurological injury would you examine for in this patient based on this x-ray? (1 mark)"},{"id":"c","label":"Part C","prompt":"What motor, sensory and tendon reflex deficits would you expect if this injury was present? (3 marks) Deficit Motor Sensory Tenon Reflex"}],"propPages":["asset:imgf46c14775bdfbf084c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 37 yo woman presents following a high speed motor vehicle accident. Her GCS is 15</div><div class=\"answer-line\"><strong>Her</strong> <strong>pelvic x-ray is attached. </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Left SIJ disrupted</div><div class=\"answer-line\">2. Right SIJ widened</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 5 year old boy presents with a 2cm linear wound on his chin after falling over. He has no other injuries. 1. Complete the table below giving three (3) different wound closure options with two (2) pros and two (2) cons for each. (12 marks) Technique Pros Cons 2.","parts":[{"id":"p1","label":"Part 1","prompt":"Outline your discharge advice to the parents. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Sutures</td><td>1. Secure closure in</td><td>1. Many need sedation</td></tr><tr><td>highly mobile area</td><td>for insertion</td><td></td></tr><tr><td>2. Good cosmetic result</td><td>2. Need to be removed</td><td></td></tr><tr><td colspan=\"3\">3. More difficult for a</td></tr><tr><td colspan=\"3\">child to pull off</td></tr><tr><td>Tissue Adhesive /Wound</td><td>1. Quick and Easy</td><td>1. Need to keep dry</td></tr><tr><td colspan=\"3\">Glue</td></tr><tr><td>2. Does not need to be</td><td>2. Less tensile strength</td><td></td></tr><tr><td>removed – Scabs off</td><td>compared with</td><td></td></tr><tr><td colspan=\"3\">Sutures</td></tr><tr><td colspan=\"3\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr><tr><td>Skin Tapes/Steri Strips</td><td>1. Quick and  Easy</td><td>1. Difficult to use in</td></tr><tr><td colspan=\"3\">places with high static</td></tr><tr><td>2. Can be used to</td><td>and dynamic forces</td><td></td></tr><tr><td colspan=\"3\">reinforce other wound</td></tr><tr><td>closure techniques</td><td>2. May come off prior to</td><td></td></tr><tr><td colspan=\"3\">wound healing</td></tr><tr><td>3. Does not require the</td><td>leading to wound</td><td></td></tr><tr><td>use of local</td><td>dehiscence</td><td></td></tr><tr><td colspan=\"3\">anaesthetic</td></tr><tr><td colspan=\"3\"><strong>Would NOT accept Staples as this would not be used in this case. </strong></td></tr><tr><td colspan=\"3\">b)   List your discharge advice to the parents. (3 marks)</td></tr><tr><td>•</td><td>Wound advice- keep dry, don’t touch, watch for signs infection</td><td></td></tr><tr><td>•</td><td>Head injury advice-return if H/A,V, altered LOC-verbal and ideally written</td><td></td></tr><tr><td>•</td><td>Planned Follow-up + Safety net-review of wound by GP</td><td></td></tr><tr><td colspan=\"3\">FACEM –Dr J Davidson/Dr P Nanaware                                                                                        FEx 2024.2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
